/* oxlint-disable i18next/no-literal-string */
import {Card} from '@sanity/ui'
import {Code} from '@sanity/ui/code'
import startCase from 'lodash-es/startCase.js'
import {useEffect} from 'react'
import {Text, Flex, Box} from 'ui5'

/**
 * @internal
 */
export interface ErrorMessageProps {
  message: string
  stack?: string
  error: unknown
  path: Array<{name: string; type: string}>
}

/**
 * @internal
 */
export function ErrorMessage({error, message, path, stack}: ErrorMessageProps) {
  useEffect(() => {
    console.error(error)
  }, [error])

  const last = path[path.length - 1]

  return (
    <Flex flexDirection="column" gap={4} padding={4}>
      <Flex flexDirection="column" gap={2}>
        <Text weight="medium" size={3} as="div" trim={true}>
          {startCase(last.type)} Error
        </Text>
      </Flex>

      <Card tone="critical" overflow="auto" padding={4}>
        <Code>{message}</Code>
      </Card>

      <Flex as="ul" flexDirection="column" gap={2}>
        {path.map(({name, type}, index) => (
          // oxlint-disable-next-line no-array-index-key
          <Flex key={index} as="li" gap={2} alignItems="center">
            <Box>
              <Code>{name}</Code>
            </Box>
            <Box>
              <Text muted size={1} as="div" trim={true}>
                {type}
              </Text>
            </Box>
          </Flex>
        ))}
      </Flex>

      {stack && (
        <details>
          <Text as="summary" trim={true}>
            Stack Trace
          </Text>

          <Box overflow="auto" marginTop={4}>
            <Code>{stack}</Code>
          </Box>
        </details>
      )}
    </Flex>
  )
}
